FROM basico.curriculo_basico this_
LEFT OUTER JOIN escola.escola escola3_ ON
this_.id_escola = escola3_.id_escola
LEFT OUTER JOIN escola.bairro_escola bairroesco4_ ON
escola3_.id_bairro_escola = bairroesco4_.id_bairro_escola
LEFT OUTER JOIN comum.municipio municipio5_ ON
bairroesco4_.id_municipio = municipio5_.id_municipio
LEFT OUTER JOIN comum.unidade_federativa unidadefed6_ ON
municipio5_.id_unidade_federativa = unidadefed6_.id_unidade_federativa
LEFT OUTER JOIN comum.municipio municipio7_ ON
unidadefed6_.id_capital = municipio7_.id_municipio
LEFT OUTER JOIN comum.pais pais8_ ON
unidadefed6_.id_pais = pais8_.id_pais
LEFT OUTER JOIN comum.conta_bancaria contabanca9_ ON
escola3_.id_conta = contabanca9_.id_conta_bancaria
LEFT OUTER JOIN comum.banco banco10_ ON
contabanca9_.id_banco = banco10_.id_banco
LEFT OUTER JOIN escola.dependencia_administrativa_escola dependenci11_ ON
escola3_.id_dependencia_administrativa = dependenci11_.id_dependencia_administrativa_escola
LEFT OUTER JOIN comum.unidade unidade12_ ON
escola3_.id_drae = unidade12_.id_unidade
LEFT OUTER JOIN escola.localizacao_zona localizaca13_ ON
escola3_.id_localizacao_zona = localizaca13_.id_localizacao_zona
LEFT OUTER JOIN comum.municipio municipio14_ ON
escola3_.id_municipio = municipio14_.id_municipio
LEFT OUTER JOIN comum.unidade unidade15_ ON
escola3_.id_regional_ensino = unidade15_.id_unidade
LEFT OUTER JOIN escola.situacao_funcionamento situacaofu16_ ON
escola3_.id_situacao_funcionamento = situacaofu16_.id_situacao_funcionamento
LEFT OUTER JOIN escola.tipo_unidade_escolar tipounidad17_ ON
escola3_.id_tipo_unidade_escolar = tipounidad17_.id_tipo_unidade_escolar
LEFT OUTER JOIN comum.unidade unidade18_ ON
escola3_.id_unidade_escola = unidade18_.id_unidade
LEFT OUTER JOIN comum.zona_municipal zonamunici19_ ON
escola3_.id_zona_municipal = zonamunici19_.id_zona_municipal
LEFT OUTER JOIN comum.municipio municipio20_ ON
zonamunici19_.id_municipio = municipio20_.id_municipio
LEFT OUTER JOIN basico.escola_curriculo ec1_ ON
this_.id_curriculo_basico = ec1_.id_curriculo_basico
LEFT OUTER JOIN escola.escola escola22_ ON
ec1_.id_escola = escola22_.id_escola
INNER JOIN basico.serie serie23_ ON
this_.id_serie = serie23_.id_serie
LEFT OUTER JOIN basico.etapa_ensino etapaensin24_ ON
serie23_.id_etapa_ensino = etapaensin24_.id_etapa_ensino
LEFT OUTER JOIN basico.forma_organizacao_etapa formaorgan25_ ON
etapaensin24_.id_forma_organizacao_Etapa = formaorgan25_.id_forma_organizacao_etapa
LEFT OUTER JOIN comum.unidade unidade26_ ON
formaorgan25_.id_unidade = unidade26_.id_unidade
LEFT OUTER JOIN basico.local_oferta localofert27_ ON
etapaensin24_.id_local_oferta = localofert27_.id_local_oferta
LEFT OUTER JOIN basico.modalidade_ensino_basico modalidade28_ ON
etapaensin24_.id_modalidade = modalidade28_.id_modalidade_ensino_basico
LEFT OUTER JOIN comum.unidade unidade29_ ON
modalidade28_.id_unidade = unidade29_.id_unidade
LEFT OUTER JOIN basico.nivel_etapa_ensino niveletapa30_ ON
etapaensin24_.id_nivel_etapa = niveletapa30_.id_nivel_etapa_ensino
LEFT OUTER JOIN comum.unidade unidade31_ ON
niveletapa30_.id_unidade = unidade31_.id_unidade
LEFT OUTER JOIN basico.situacao_etapa_ensino situacaoet32_ ON
etapaensin24_.id_situacao = situacaoet32_.id_situacao
LEFT OUTER JOIN comum.unidade unidade33_ ON
etapaensin24_.id_unidade = unidade33_.id_unidade
LEFT OUTER JOIN comum.unidade unidade34_ ON
serie23_.id_unidade = unidade34_.id_unidade
LEFT OUTER JOIN ensino.turno turno35_ ON
this_.id_turno = turno35_.id_turno
LEFT OUTER JOIN comum.unidade unidade36_ ON
this_.id_unidade = unidade36_.id_unidade
WHERE this_.ativo 
AND this_.id_serie = 15290011
--AND this_.ano_entrada_vigor = null
AND (this_.id_turno IS NULL 	OR this_.id_turno =6)
AND this_.id_unidade =605
ORDER BY this_.ano_entrada_vigor DESC, this_.id_escola DESC, this_.id_turno DESC, this_.id_curriculo_basico DESC
LIMIT 1;
